import React, { useMemo } from 'react';

const GEM_COLORS = [
  '#e0115f', '#50c878', '#4169e1', '#9b59b6',
  '#ffbf00', '#b9f2ff', '#ff6b9d', '#00d4aa',
];

function srand(seed) {
  const x = Math.sin(seed * 9301 + 49297) * 233280;
  return x - Math.floor(x);
}

export default function TreasureChest({ count = 0, size = 'md' }) {
  const dims = size === 'sm'
    ? { w: 32, h: 44, neck: 18, neckH: 7, lidW: 22, gemR: 1.0 }
    : size === 'lg'
    ? { w: 52, h: 68, neck: 30, neckH: 11, lidW: 36, gemR: 1.4 }
    : { w: 40, h: 54, neck: 24, neckH: 9, lidW: 28, gemR: 1.2 };

  const { w, h, neck, neckH, lidW, gemR } = dims;
  const bodyH = h - neckH;
  const pad = 4;
  const svgW = w + pad * 2;
  const svgH = h + 6;

  const gems = useMemo(() => {
    if (count === 0) return [];
    const result = [];
    const n = Math.min(count, 150);
    const innerL = pad + 3;
    const innerR = pad + w - 3;
    const jarBottom = neckH + bodyH - 2;
    const jarTop = neckH + 2;
    const usableH = jarBottom - jarTop;

    // How high the pile reaches: 150 gems = 95% of jar
    const pileTop = jarBottom - (n / 150) * usableH * 0.95;

    for (let i = 0; i < n; i++) {
      // Random position within the filled zone
      const cx = innerL + srand(i * 7 + 1) * (innerR - innerL);
      // Bias toward bottom: use square root to cluster at bottom
      const t = srand(i * 13 + 3);
      const cy = jarBottom - Math.sqrt(t) * (jarBottom - pileTop);

      result.push({
        cx,
        cy,
        color: GEM_COLORS[Math.floor(srand(i * 11 + 5) * GEM_COLORS.length)],
        rot: srand(i * 17 + 7) * 360, // random rotation
        bright: srand(i * 23) > 0.6,
      });
    }
    return result;
  }, [count, w, pad, neckH, bodyH]);

  const uid = `jar-${size}`;

  return (
    <div className="relative flex flex-col items-center" style={{ width: svgW, height: svgH + 14 }}>
      {count > 0 && (
        <div
          className="absolute inset-0 rounded-full blur-lg"
          style={{ background: `radial-gradient(circle, rgba(255,215,0,${0.05 + Math.min(count / 150, 1) * 0.15}) 0%, transparent 70%)` }}
        />
      )}

      {count >= 100 && (
        <>
          <span className="absolute -top-1 left-0 text-[7px] animate-pulse">✨</span>
          <span className="absolute top-1 -right-1 text-[7px] animate-pulse" style={{ animationDelay: '0.7s' }}>✨</span>
        </>
      )}

      <svg width={svgW} height={svgH} viewBox={`0 0 ${svgW} ${svgH}`} className="relative z-10">
        <defs>
          <linearGradient id={`g-${uid}`} x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="rgba(255,255,255,0.14)" />
            <stop offset="30%" stopColor="rgba(255,255,255,0.03)" />
            <stop offset="70%" stopColor="rgba(255,255,255,0.02)" />
            <stop offset="100%" stopColor="rgba(255,255,255,0.11)" />
          </linearGradient>
          <linearGradient id={`s-${uid}`} x1="0" y1="0" x2="0.3" y2="1">
            <stop offset="0%" stopColor="rgba(255,255,255,0.28)" />
            <stop offset="100%" stopColor="rgba(255,255,255,0)" />
          </linearGradient>
          <clipPath id={`c-${uid}`}>
            <rect x={pad + 1.5} y={neckH + 0.5} width={w - 3} height={bodyH - 2} rx={5} />
            <rect x={pad + (w - neck) / 2 + 0.5} y={2} width={neck - 1} height={neckH + 2} rx={2} />
          </clipPath>
        </defs>

        {/* Jar neck */}
        <rect
          x={pad + (w - neck) / 2} y={2}
          width={neck} height={neckH + 2}
          rx={3} fill="rgba(255,255,255,0.05)"
          stroke="rgba(255,255,255,0.2)" strokeWidth={1.2}
        />
        {/* Cork */}
        <rect
          x={pad + (w - lidW) / 2} y={0}
          width={lidW} height={4.5} rx={2.2}
          fill="rgba(255,215,0,0.5)" stroke="rgba(255,215,0,0.75)" strokeWidth={0.8}
        />
        {/* Jar body */}
        <rect
          x={pad} y={neckH}
          width={w} height={bodyH} rx={6}
          fill={`url(#g-${uid})`}
          stroke="rgba(255,255,255,0.2)" strokeWidth={1.2}
        />

        {/* Gems */}
        <g clipPath={`url(#c-${uid})`}>
          {gems.map((gem, i) => (
            <polygon
              key={i}
              points={`0,${-gemR} ${gemR * 0.7},0 0,${gemR * 0.55} ${-gemR * 0.7},0`}
              transform={`translate(${gem.cx},${gem.cy}) rotate(${gem.rot})`}
              fill={gem.color}
              opacity={gem.bright ? 1 : 0.7}
            />
          ))}
        </g>

        {/* Glass shine */}
        <rect
          x={pad + 2} y={neckH + 2}
          width={w * 0.2} height={bodyH - 5} rx={3}
          fill={`url(#s-${uid})`}
        />
        <rect
          x={pad + (w - neck) / 2 + 2} y={3}
          width={neck * 0.18} height={neckH - 1} rx={1}
          fill="rgba(255,255,255,0.16)"
        />
      </svg>

      <span className="text-[10px] font-bold text-gold mt-0.5">{count}</span>
    </div>
  );
}
